class BenefitReconciliationStatus(str, Enum):
    CONCILIADO = "CONCILIADO"
    EXCEPCION = "EXCEPCION"


class BenefitReconciliationIssue(str, Enum):
    MONTO_AJUSTE_DIFERENTE = "MONTO_AJUSTE_DIFERENTE"
    MONTO_FINAL_DIFERENTE = "MONTO_FINAL_DIFERENTE"
    REFERENCIA_TRANSACCION_DIFERENTE = "REFERENCIA_TRANSACCION_DIFERENTE"
    REFERENCIA_PROVEEDOR_FALTANTE = "REFERENCIA_PROVEEDOR_FALTANTE"
    EVIDENCIA_FALTANTE = "EVIDENCIA_FALTANTE"
    APLICACION_DUPLICADA = "APLICACION_DUPLICADA"
    APLICACION_CONFIRMADA_FALTANTE = "APLICACION_CONFIRMADA_FALTANTE"


@dataclass(frozen=True)
class BenefitReconciliationExpected:
    application_id: str
    source_transaction_id: str
    expected_adjustment_amount: float
    expected_final_amount: float


@dataclass(frozen=True)
class BenefitReconciliationObserved:
    application_id: str
    source_transaction_id: str
    confirmed: bool
    observed_adjustment_amount: Optional[float]
    observed_final_amount: Optional[float]
    provider_reference: Optional[str]
    evidence_reference: Optional[str]
    confirmation_count: int = 0


@dataclass(frozen=True)
class BenefitReconciliationResult:
    application_id: str
    status: BenefitReconciliationStatus
    issues: tuple[BenefitReconciliationIssue, ...]


def reconcile_benefit_application(expected: BenefitReconciliationExpected, observed: BenefitReconciliationObserved, tolerance: float = 0.01) -> BenefitReconciliationResult:
    if tolerance < 0:
        raise ValueError("tolerance no puede ser negativa")
    if not str(expected.application_id or "").strip() or not str(observed.application_id or "").strip():
        raise ValueError("application_id es obligatorio")
    if expected.application_id != observed.application_id:
        raise ValueError("No se pueden conciliar aplicaciones diferentes")
    issues = []
    if expected.source_transaction_id != observed.source_transaction_id:
        issues.append(BenefitReconciliationIssue.REFERENCIA_TRANSACCION_DIFERENTE)
    if observed.confirmation_count > 1:
        issues.append(BenefitReconciliationIssue.APLICACION_DUPLICADA)
    if not observed.confirmed:
        issues.append(BenefitReconciliationIssue.APLICACION_CONFIRMADA_FALTANTE)
    if observed.confirmed and not str(observed.provider_reference or "").strip():
        issues.append(BenefitReconciliationIssue.REFERENCIA_PROVEEDOR_FALTANTE)
    if observed.confirmed and not str(observed.evidence_reference or "").strip():
        issues.append(BenefitReconciliationIssue.EVIDENCIA_FALTANTE)
    if observed.confirmed and observed.observed_adjustment_amount is not None:
        if abs(float(expected.expected_adjustment_amount) - float(observed.observed_adjustment_amount)) > tolerance:
            issues.append(BenefitReconciliationIssue.MONTO_AJUSTE_DIFERENTE)
    if observed.confirmed and observed.observed_final_amount is not None:
        if abs(float(expected.expected_final_amount) - float(observed.observed_final_amount)) > tolerance:
            issues.append(BenefitReconciliationIssue.MONTO_FINAL_DIFERENTE)
    return BenefitReconciliationResult(
        application_id=expected.application_id,
        status=BenefitReconciliationStatus.CONCILIADO if not issues else BenefitReconciliationStatus.EXCEPCION,
        issues=tuple(issues),
    )


def reconciliation_exception_requires_operational_task(result: BenefitReconciliationResult) -> bool:
    return result.status == BenefitReconciliationStatus.EXCEPCION


def reconciliation_can_mutate_original_transaction() -> bool:
    return False

from modules.cava_socios.domain import (
    BenefitReconciliationExpected,
    BenefitReconciliationIssue,
    BenefitReconciliationObserved,
    BenefitReconciliationStatus,
    reconcile_benefit_application,
    reconciliation_can_mutate_original_transaction,
    reconciliation_exception_requires_operational_task,
)


def _expected(**overrides):
    data = dict(application_id="APP-1", source_transaction_id="TX-1", expected_adjustment_amount=100.0, expected_final_amount=900.0)
    data.update(overrides)
    return BenefitReconciliationExpected(**data)


def _observed(**overrides):
    data = dict(application_id="APP-1", source_transaction_id="TX-1", confirmed=True, observed_adjustment_amount=100.0, observed_final_amount=900.0, provider_reference="POS-REF-1", evidence_reference="EVID-1", confirmation_count=1)
    data.update(overrides)
    return BenefitReconciliationObserved(**data)


def test_matching_application_is_reconciled():
    result = reconcile_benefit_application(_expected(), _observed())
    assert result.status == BenefitReconciliationStatus.CONCILIADO
    assert result.issues == ()


def test_amount_difference_creates_exception():
    result = reconcile_benefit_application(_expected(), _observed(observed_adjustment_amount=90.0))
    assert result.status == BenefitReconciliationStatus.EXCEPCION
    assert BenefitReconciliationIssue.MONTO_AJUSTE_DIFERENTE in result.issues


def test_duplicate_confirmation_is_detected():
    result = reconcile_benefit_application(_expected(), _observed(confirmation_count=2))
    assert BenefitReconciliationIssue.APLICACION_DUPLICADA in result.issues


def test_missing_confirmation_is_detected():
    result = reconcile_benefit_application(_expected(), _observed(confirmed=False, observed_adjustment_amount=None, observed_final_amount=None, provider_reference=None, evidence_reference=None, confirmation_count=0))
    assert BenefitReconciliationIssue.APLICACION_CONFIRMADA_FALTANTE in result.issues


def test_missing_provider_evidence_is_detected():
    result = reconcile_benefit_application(_expected(), _observed(provider_reference=None, evidence_reference=None))
    assert BenefitReconciliationIssue.REFERENCIA_PROVEEDOR_FALTANTE in result.issues
    assert BenefitReconciliationIssue.EVIDENCIA_FALTANTE in result.issues


def test_transaction_reference_mismatch_is_detected():
    result = reconcile_benefit_application(_expected(), _observed(source_transaction_id="TX-OTHER"))
    assert BenefitReconciliationIssue.REFERENCIA_TRANSACCION_DIFERENTE in result.issues


def test_exception_requires_followup_task():
    result = reconcile_benefit_application(_expected(), _observed(observed_final_amount=850.0))
    assert reconciliation_exception_requires_operational_task(result) is True


def test_reconciliation_never_mutates_original_transaction():
    assert reconciliation_can_mutate_original_transaction() is False
